code_example:
float low_precision = 10.0f;
double high_precision = 5.0;

// Rule: In binary operations, the float operand
// is implicitly promoted to double precision.
auto result_type_is_double = low_precision * high_precision;

// Also occurs when mixing with default double literals (e.g., 2.5)
auto literal_promotion = low_precision + 2.5;

// Resulting types:
decltype(result_type_is_double) d1; // d1 is double
decltype(literal_promotion) d2;     // d2 is double
